 if(v==='missions'){const missions=[['Primer contacto','Completa tu primer combate.','completed',100],['Sin pestañear','Gana 3 combates.','wins',150],['Prueba de fuerza','Usa una habilidad definitiva.','ult',120]];body.innerHTML=`<div class="mission-grid">${missions.map((m,i)=>{const done=m[2]==='completed'?profile.completed>0:m[2]==='wins'?profile.wins>=3:profile.claimed.includes('ult');const claimed=profile.claimed.includes(m[2]);return `<article class="panel-card"><p class="eyebrow">MISIÓN DIARIA · 0${i+1}</p><h3>${m[0]}</h3><p>${m[1]}</p><div class="mission-progress"><i style="width:${done?100:m[2]==='wins'?Math.min(profile.wins/3*100,99):0}%"></i></div><p>${done?'OBJETIVO COMPLETADO':'EN PROGRESO'} · +${m[3]} ◈</p><button class="small-btn claim-btn" data-key="${m[2]}" data-reward="${m[3]}" ${!done||claimed?'disabled':''}>${claimed?'RECOMPENSA COBRADA':done?'COBRAR RECOMPENSA':'CONTINUAR'}</button></article>`}).join('')}</div>`;$$('.claim-btn').forEach(b=>b.onclick=()=>{if(b.disabled)return;profile.coins+=+b.dataset.reward;profile.claimed.push(b.dataset.key);save();renderContent('missions');toast('Recompensa añadida a tu cartera.');});}
 if(v==='online'){body.innerHTML=`<div class="online-grid"><article class="panel-card"><p class="eyebrow">EMPAREJAMIENTO · BETA</p><h3>BUSCAR RIVAL</h3><p>El sistema de esta versión prototipo simula una cola de búsqueda local y entra en combate contra una IA de nivel competitivo.</p><div class="online-status"><i class="pulse"></i> SERVIDOR DE PRUEBA DISPONIBLE</div><br><button class="small-btn" id="queueBtn">BUSCAR PARTIDA ↗</button></article><article class="panel-card"><p class="eyebrow">SALA PRIVADA</p><h3>JUGAR CON AMIGOS</h3><p>El multijugador en red requiere un servidor dedicado. Puedes crear una sala local de práctica para probar el combate con un rival IA.</p><button class="small-btn" id="roomBtn">CREAR SALA DE PRÁCTICA</button></article><article class="panel-card"><p class="eyebrow">ESTADO DE RED</p><h3>PROTOCOLO 0.9</h3><p>Emparejamiento online real no está conectado en esta demo. Las partidas jugables contra IA funcionan sin conexión.</p><p class="online-status"><i class="pulse"></i> COMBATE LOCAL ACTIVO</p></article></div>`;$('#queueBtn').onclick=()=>{const b=$('#queueBtn');b.textContent='BUSCANDO RIVAL…';b.disabled=true;setTimeout(()=>{playerIndex=customIndex;enemyIndex=(playerIndex+1+Math.floor(Math.random()*14))%15;arenaIndex=Math.floor(Math.random()*5);initFight(false);setView('fight');toast('Rival encontrado.');},1200);};$('#roomBtn').onclick=()=>{playerIndex=customIndex;enemyIndex=(playerIndex+1)%15;arenaIndex=4;initFight(true);setView('fight');};}
}

function initFight(training){fight={training,player:{x:.32,hp:100,ult:0,face:1,state:'idle',stateTime:0,attackCd:0,skillCd:[0,0,0],block:false,combo:0},enemy:{x:.68,hp:100,ult:0,face:-1,state:'idle',stateTime:0,attackCd:0,skillCd:[0,0,0],block:false,combo:0},particles:[],projectiles:[],elapsed:0,over:false,won:false,round:1,aiTimer:1,usedUlt:false};$('#pausePanel').classList.add('hidden');$('#resultPanel').classList.add('hidden');$('#fightMessage').textContent='';$('#fightMessage').classList.remove('show');$('#arenaLabel').textContent=arenas[arenaIndex].toUpperCase();$('#roundCount').textContent='01';$('#playerHudName').textContent=fighters[playerIndex].name;$('#enemyHudName').textContent=fighters[enemyIndex].name;['skillLabel1','skillLabel2','skillLabel3'].forEach((id,i)=>$('#'+id).textContent=fighters[playerIndex].skills[i].split(' ')[0].slice(0,8).toUpperCase());updateHud();if(!fight.training)showFightWord('PREPÁRATE');setTimeout(()=>{if(view==='fight'&&fight&&!fight.over)showFightWord('¡LUCHA!');},650);}
function showFightWord(s){const m=$('#fightMessage');m.textContent=s;m.classList.add('show');clearTimeout(m._timer);m._timer=setTimeout(()=>m.classList.remove('show'),900);}
function updateHud(){if(!fight)return;$('#playerHealth').style.width=Math.max(0,fight.player.hp)+'%';$('#enemyHealth').style.width=Math.max(0,fight.enemy.hp)+'%';$('#playerUlt').style.width=fight.player.ult+'%';$('#enemyUlt').style.width=fight.enemy.ult+'%';$$('.skill-btn').forEach((b,i)=>{const cd=fight.player.skillCd[i]||0;b.classList.toggle('cooling',cd>0);b.querySelector('i').style.transform=`scaleY(${Math.min(1,cd/[4,6,9][i])})`;});$('#ult').classList?.toggle('ready',fight.player.ult>=100);}
function playerAction(action){if(view!=='fight'||!fight||fight.over||$('#pausePanel').classList.contains('hidden')===false)return;const p=fight.player,e=fight.enemy;let d=Math.abs(p.x-e.x),f=fighters[playerIndex];if(action==='block'){p.block=true;p.state='block';p.stateTime=.18;return;}if(action==='attack'){if(p.attackCd>0)return;p.attackCd=.43;p.state='attack';p.stateTime=.28;p.combo++;if(d<.19){const dmg=7+(p.combo%3===0?4:0);damage(e,dmg,!!e.block);p.ult=Math.min(100,p.ult+8);burst((p.x+e.x)/2,randomY(),f.accent,8);}else burst(p.x+(e.x>p.x?.11:-.11),fightY()-.35,f.accent,3);return;}
 if(action.startsWith('skill')){let i=+action.slice(-1)-1,cd=[4,6,9][i];if(p.skillCd[i]>0)return;p.skillCd[i]=cd;p.state='attack';p.stateTime=.4;if(i===0){if(d<.43){damage(e,14,!!e.block);p.ult=Math.min(100,p.ult+15);burst((p.x+e.x)/2,randomY(),f.accent,16);}else projectile(p,e,11,f.accent,0);}else if(i===1){p.x+=(e.x>p.x?1:-1)*.075;p.x=clamp(p.x,.12,.88);if(Math.abs(p.x-e.x)<.22){damage(e,19,!!e.block);p.ult=Math.min(100,p.ult+18);burst((p.x+e.x)/2,randomY(),f.accent,20);}else projectile(p,e,16,f.accent,1);}else{projectile(p,e,10,f.accent,2);if(d<.32){damage(e,10,!!e.block);e.state='hit';e.stateTime=.5;}}return;}
 if(action==='ult'){if(p.ult<100){toast('La barra ULTI aún no está llena.');return;}p.ult=0;fight.usedUlt=true;p.state='attack';p.stateTime=.8;showFightWord(['VACÍO ABSOLUTO','HASTA LA MUERTE','BANQUETE FINAL','JARDÍN DE NADIE','BISAGRA FINAL'][playerIndex%5]);if(d<.5){damage(e,32,!!e.block);burst((p.x+e.x)/2,randomY(),f.accent,34);}else projectile(p,e,28,f.accent,3);}
}
function damage(target,amount,blocked){let n=blocked?Math.ceil(amount*.27):amount;target.hp=Math.max(0,target.hp-n);if(target===fight.enemy){fight.player.ult=Math.min(100,fight.player.ult+(blocked?4:Math.ceil(n*.55)));}else{fight.enemy.ult=Math.min(100,fight.enemy.ult+(blocked?4:Math.ceil(n*.5)));}if(!blocked){target.state='hit';target.stateTime=.28;target.x=clamp(target.x+(target===fight.enemy?.025:-.025),.1,.9);}if(target.hp<=0)finishFight(target===fight.enemy);}
function projectile(owner,target,damageVal,color,kind){fight.projectiles.push({x:owner.x,y:kind===3?.48:.58,target:target,xTarget:target.x,speed:kind===3?.82:.61,damage:damageVal,color,kind,life:1.6});}
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function fightY(){return .69}function randomY(){return rand(.45,.67)}
function burst(x,y,color,n){if(!fight)return;for(let i=0;i<n;i++)fight.particles.push({x,y,vx:rand(-.38,.38),vy:rand(-.62,.1),life:rand(.22,.7),max:.7,color,size:rand(2,7)});}
function finishFight(won){if(!fight||fight.over)return;fight.over=true;fight.won=won;fight.player.block=false;$('#resultPanel').classList.remove('hidden');$('#pausePanel').classList.add('hidden');$('#resultTitle').textContent=won?'VICTORIA.':'DERROTA.';$('#resultCopy').textContent=won?'Has sobrevivido a la anomalía. El archivo te reconoce.':'La anomalía sigue en pie. Todavía puedes volver.';let reward=won?(fight.training?0:80):0;$('#rewardCoins').textContent=reward;if(won&&!fight.training){profile.coins+=reward;profile.wins++;}if(!fight.training)profile.completed++;if(fight.usedUlt)profile.claimed.includes('ult')||profile.claimed.push('ult');save();$('#resultPanel .reward-line').style.display=reward?'flex':'none';if(fight.training)$('#resultCopy').textContent='Sesión terminada. La práctica no afecta tu progreso.';}
function startLoop(){if(!last)last=performance.now();requestAnimationFrame(loop);}
function loop(now){if(view!=='fight')return;let dt=Math.min(.034,(now-last)/1000||.016);last=now;if(fight&&!fight.over&&!$('#pausePanel').classList.contains('hidden')){}else if(fight&&!fight.over)step(dt);render();requestAnimationFrame(loop);}
let moveAxis=0, keys={};
function step(dt){const p=fight.player,e=fight.enemy;fight.elapsed+=dt;for(const a of [p,e]){a.attackCd=Math.max(0,a.attackCd-dt);a.skillCd=a.skillCd.map(c=>Math.max(0,c-dt));a.stateTime-=dt;if(a.stateTime<=0&&a.state!=='block')a.state='idle';}
 p.face=e.x>=p.x?1:-1;e.face=p.x>=e.x?1:-1;if(!p.block){p.x=clamp(p.x+moveAxis*dt*.48,.08,.92);if(moveAxis!==0&&p.state==='idle')p.state='move';}if(!p.block&&keys['ArrowLeft'])p.x=clamp(p.x-dt*.42,.08,.92);if(!p.block&&keys['ArrowRight'])p.x=clamp(p.x+dt*.42,.08,.92);if(keys['ArrowUp']||keys['w'])p.x=clamp(p.x-dt*.01,.08,.92);
 fight.aiTimer-=dt;const dist=Math.abs(e.x-p.x),toward=p.x>e.x?1:-1;if(fight.aiTimer<=0){fight.aiTimer=rand(.38,.8);if(dist>.22)e.x=clamp(e.x+toward*rand(.04,.12),.1,.9);else if(Math.random()<.57){if(e.ult>=100&&Math.random()<.23){e.ult=0;showFightWord('¡CUIDADO!');if(dist<.43)damage(p,24,!!p.block);else projectile(e,p,22,fighters[enemyIndex].accent,3);}else if(Math.random()<.43&&e.skillCd[0]<=0){e.skillCd[0]=4.2;damage(p,dist<.34?13:8,!!p.block);e.ult=Math.min(100,e.ult+12);if(dist>=.34)projectile(e,p,8,fighters[enemyIndex].accent,0);burst((p.x+e.x)/2,.57,fighters[enemyIndex].accent,11);}else if(e.attackCd<=0){e.attackCd=.68;damage(p,8,!!p.block);e.state='attack';e.stateTime=.27;}}else if(dist<.28)e.state='block';else e.state='idle';}
 if(e.state==='block'&&Math.random()<.02)e.state='idle';for(let i=fight.projectiles.length-1;i>=0;i--){let b=fight.projectiles[i];b.life-=dt;let sign=b.target.x>b.x?1:-1;b.x+=sign*b.speed*dt;if(Math.abs(b.target.x-b.x)<.05||b.life<=0){if(Math.abs(b.target.x-b.x)<.06&&b.target.hp>0){damage(b.target,b.damage,!!b.target.block);burst(b.x,b.y,b.color,12);}fight.projectiles.splice(i,1);}}
 for(let i=fight.particles.length-1;i>=0;i--){const a=fight.particles[i];a.life-=dt;a.x+=a.vx*dt;a.y+=a.vy*dt;a.vy+=1.2*dt;if(a.life<=0)fight.particles.splice(i,1);}updateHud();}
function render(){const r=canvas.getBoundingClientRect(),w=r.width,h=r.height;if(!w||!h)return;ctx.clearRect(0,0,w,h);if(view==='fight'&&fight)renderFight(w,h);else if(view==='home'||view==='select'||['fighters','customize'].includes(view))renderAtmosphere(w,h);}
function renderAtmosphere(w,h){let grad=ctx.createRadialGradient(w*.76,h*.46,0,w*.76,h*.46,Math.max(w,h)*.75);grad.addColorStop(0,'#2d2230');grad.addColorStop(.58,'#18131b');grad.addColorStop(1,'#100d12');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);ctx.strokeStyle='#c2a3ce0b';ctx.lineWidth=1;for(let i=0;i<8;i++){let x=w*(.59+i*.055);ctx.beginPath();ctx.moveTo(x,85);ctx.lineTo(x+Math.sin(performance.now()/4000+i)*16,h-65);ctx.stroke();}ctx.fillStyle='#e945480a';ctx.beginPath();ctx.arc(w*.81,h*.46,Math.min(w,h)*.32,0,7);ctx.fill();}
function renderFight(w,h){let pal=arenaColors[arenaIndex];let bg=ctx.createLinearGradient(0,0,0,h);bg.addColorStop(0,pal[0]);bg.addColorStop(.62,'#1c1820');bg.addColorStop(1,'#100d12');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);let horizon=h*.66;
 // distant architecture / arena silhouettes
 if(arenaIndex===0){for(let i=0;i<13;i++){let x=i*w/12;ctx.fillStyle=i%2?'#362139':'#49283d';ctx.beginPath();ctx.arc(x,horizon-42+(i%3)*8,34,Math.PI,0);ctx.fill();ctx.fillRect(x-34,horizon-42,68,45);ctx.fillStyle=pal[2];ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(x,horizon-42,5,0,7);ctx.fill();ctx.globalAlpha=1;}}
 else if(arenaIndex===1){for(let i=0;i<12;i++){let x=i*w/11;let bh=rand(45,180);ctx.fillStyle=i%2?'#22343a':'#253137';ctx.fillRect(x-18,horizon-bh,36,bh);ctx.fillStyle='#d9544a44';for(let y=horizon-bh+12;y<horizon-10;y+=20)ctx.fillRect(x-9,y,5,8);}}
 else if(arenaIndex===2){ctx.strokeStyle='#75cba022';for(let i=0;i<10;i++){let x=i*w/9;ctx.strokeRect(x-30,horizon-150,60,130);ctx.beginPath();ctx.moveTo(x,horizon-148);ctx.lineTo(x,horizon-20);ctx.stroke();}}
 else if(arenaIndex===3){for(let i=0;i<12;i++){let x=i*w/11;ctx.strokeStyle=i%2?'#526341':'#647343';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(x,horizon);ctx.lineTo(x+rand(-40,40),horizon-120-rand(0,80));ctx.stroke();ctx.beginPath();ctx.arc(x+rand(-40,40),horizon-150,30,0,7);ctx.fillStyle='#364633';ctx.fill();}}
 else{ctx.fillStyle='#292931';ctx.fillRect(0,horizon-85,w,90);ctx.fillStyle='#37343a';ctx.fillRect(w*.08,horizon-138,w*.84,48);ctx.fillStyle=pal[2];ctx.fillRect(w*.16,horizon-133,4,36);ctx.fillRect(w*.84,horizon-133,4,36);ctx.fillStyle='#202027';for(let x=0;x<w;x+=70)ctx.fillRect(x,horizon-78,48,3);}
 // atmospheric lights
 let glow=ctx.createRadialGradient(w*.5,horizon-110,2,w*.5,horizon-110,w*.46);glow.addColorStop(0,pal[1]+'55');glow.addColorStop(1,pal[1]+'00');ctx.fillStyle=glow;ctx.fillRect(0,0,w,horizon+20);
 ctx.fillStyle='#17131a';ctx.fillRect(0,horizon,w,h-horizon);ctx.fillStyle='#493849';ctx.fillRect(0,horizon,w,2);ctx.strokeStyle='#ded1e00e';for(let i=-5;i<14;i++){ctx.beginPath();ctx.moveTo(w*.5,horizon);ctx.lineTo(i*w/8,h);ctx.stroke();}for(let j=1;j<5;j++){let y=horizon+(h-horizon)*j*j/25;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}
 if(!fight.over){const p=fight.player,e=fight.enemy;const ground=horizon+(h-horizon)*.51;drawCharacter(ctx,w*p.x,ground,Math.min(w,h)*.00165,fighters[playerIndex],fight.elapsed,p.face,p.state,profile.skin);drawCharacter(ctx,w*e.x,ground,Math.min(w,h)*.00165,fighters[enemyIndex],fight.elapsed,e.face,e.state,0);}
 for(const a of fight.particles){ctx.globalAlpha=Math.max(0,a.life/a.max);ctx.fillStyle=a.color;ctx.beginPath();ctx.arc(a.x*w,a.y*h,a.size,0,7);ctx.fill();}ctx.globalAlpha=1;for(const b of fight.projectiles){ctx.shadowBlur=18;ctx.shadowColor=b.color;ctx.fillStyle=b.color;ctx.beginPath();ctx.ellipse(w*b.x,h*b.y,16,6,0,0,7);ctx.fill();ctx.shadowBlur=0;}
 // hit-screen vignette
 let v=ctx.createRadialGradient(w/2,h/2,h*.2,w/2,h/2,h*.78);v.addColorStop(0,'#0000');v.addColorStop(1,'#08060999');ctx.fillStyle=v;ctx.fillRect(0,0,w,h);
}

