window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;if(e.key==='Shift'){fight&&(fight.player.block=false);}});
function togglePause(){if(!fight||fight.over)return;const p=$('#pausePanel');p.classList.toggle('hidden');fight.player.block=false;}
$('#fightExit').onclick=togglePause;$('#resumeBtn').onclick=()=>$('#pausePanel').classList.add('hidden');$('#quitFight').onclick=()=>{fight=null;setView('home');};$('#rematchBtn').onclick=()=>{initFight(fight.training);};$('#resultHome').onclick=()=>{fight=null;setView('home');};
$$('.action-btn').forEach(b=>{const action=b.dataset.action;if(action==='block'){b.addEventListener('pointerdown',e=>{e.preventDefault();fight&&(fight.player.block=true,fight.player.state='block');b.classList.add('pressed');});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>{if(fight)fight.player.block=false;b.classList.remove('pressed');}));}else{b.addEventListener('pointerdown',e=>{e.preventDefault();b.classList.add('pressed');playerAction(action);});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>b.classList.remove('pressed')));}});
const joy=$('#joystick'),knob=$('#joyKnob');let joyPointer=null;function joyMove(e){const r=joy.getBoundingClientRect(),cx=r.left+r.width/2,dx=e.clientX-cx,lim=r.width*.34;moveAxis=clamp(dx/lim,-1,1);knob.style.transform=`translate(${clamp(dx,-lim,lim)}px, ${clamp(e.clientY-(r.top+r.height/2),-lim,lim)}px)`;}joy.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);joyMove(e)});joy.addEventListener('pointermove',e=>{if(joyPointer===e.pointerId)joyMove(e)});function joyReset(){joyPointer=null;moveAxis=0;knob.style.transform='translate(0,0)';}joy.addEventListener('pointerup',joyReset);joy.addEventListener('pointercancel',joyReset);
$('#soundBtn').onclick=()=>{soundOn=!soundOn;$('#soundBtn').textContent=soundOn?'♫':'♩';toast(soundOn?'Audio de interfaz activado.':'Audio de interfaz silenciado.');};
$('#arenaSelect').addEventListener('change',e=>arenaIndex=+e.target.value);
renderArt();$('#coinCount').textContent=profile.coins;setView('home');
})();

