// Core 1v1 combat simulation.
let trainingMode=false, actionCooldowns={}, aiClock=0, fightMessageTimer=0, round=1;
function beginFight(){trainingMode=!!(fight&&fight.training);fight={player:{x:0,hp:100,ult:0,facing:1,pose:'idle',poseUntil:0,guard:false},enemy:{x:0,hp:100,ult:0,facing:-1,pose:'idle',poseUntil:0,guard:false},training:trainingMode,over:false,paused:false,started:performance.now()/1000};actionCooldowns={};aiClock=0;round++;playerIndex=selected;enemyIndex=(selected+1+Math.floor(Math.random()*(fighters.length-1)))%fighters.length;$('#arenaLabel').textContent=arenas[arenaIndex].toUpperCase();$('#roundCount').textContent=String(round).padStart(2,'0');$('#playerHudName').textContent=fighters[playerIndex].name;$('#enemyHudName').textContent=fighters[enemyIndex].name;fighters[playerIndex].skills.forEach((s,i)=>$('#skillLabel'+(i+1)).textContent=s.toUpperCase());$('#pausePanel').classList.add('hidden');$('#resultPanel').classList.add('hidden');$('#fightMessage').classList.remove('show');showView('fight');showMessage('¡A LUCHAR!')}
function showMessage(text){const e=$('#fightMessage');e.textContent=text;e.classList.add('show');clearTimeout(fightMessageTimer);fightMessageTimer=setTimeout(()=>e.classList.remove('show'),900)}
function doAction(action){if(view!=='fight'||!fight||fight.paused||fight.over)return;const p=fight.player,e=fight.enemy,now=performance.now()/1000;if(action==='block'){p.guard=true;return}const cd=action==='attack'?.34:action==='ult'?1.1:1.55;if((actionCooldowns[action]||0)>now)return;if(action==='ult'&&p.ult<100){toast('Carga la definitiva conectando golpes.');return}actionCooldowns[action]=now+cd;p.pose='attack';p.poseUntil=now+.25;const skill=action.startsWith('skill'),ultimate=action==='ult';let dist=Math.abs(e.x-p.x),range=ultimate?470:skill?345:145;let power=fighters[playerIndex].stats[0],damage=ultimate?38:skill?14+power*.055:7+power*.055;if(dist<range){if(e.guard)damage*=.22;e.hp=Math.max(0,e.hp-damage);e.pose='hit';e.poseUntil=now+.24;p.ult=Math.min(100,p.ult+(ultimate?0:skill?16:9));e.ult=Math.min(100,e.ult+damage*.25);if(ultimate){p.ult=0;showMessage('DEFINITIVA')}else if(skill)showMessage(fighters[playerIndex].skills[+action.slice(-1)-1].toUpperCase());if(e.hp<=0)finishFight(true)}else if(ultimate)showMessage('AL VACÍO');updateHud()}
function updateHud(){if(!fight)return;$('#playerHealth').style.width=fight.player.hp+'%';$('#enemyHealth').style.width=fight.enemy.hp+'%';$('#playerUlt').style.width=fight.player.ult+'%';$('#enemyUlt').style.width=fight.enemy.ult+'%';$('#playerHealth').style.filter=fight.player.hp<30?'brightness(1.45)':'none';$$('.skill-btn').forEach((b,i)=>b.classList.toggle('cooling',(actionCooldowns['skill'+(i+1)]||0)>performance.now()/1000));$$('[data-action="ult"]').forEach(b=>b.classList.toggle('cooling',fight.player.ult<100))}
function finishFight(won){if(!fight||fight.over)return;fight.over=true;fight.player.pose='idle';fight.enemy.pose='idle';const reward=trainingMode?0:won?80:30;$('#resultTitle').textContent=won?'VICTORIA.':'DERROTA.';$('#resultCopy').textContent=trainingMode?'Práctica terminada. Cada golpe cuenta.':won?'Has sobrevivido a la anomalía. El ring recuerda.':'La anomalía te ha devuelto al otro lado.';$('#rewardCoins').textContent=reward;$('#resultPanel').classList.remove('hidden');if(!trainingMode){profile.coins+=reward;profile.completed++;if(won)profile.wins++;save()}updateHud()}
function togglePause(){if(view!=='fight'||!fight||fight.over)return;fight.paused=!fight.paused;$('#pausePanel').classList.toggle('hidden',!fight.paused)}
function drawArena(w,h,t){const pal=palettes[arenaIndex]||palettes[0];let sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#100d16');sky.addColorStop(.58,pal[0]);sky.addColorStop(1,'#111016');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.save();ctx.globalAlpha=.35;ctx.fillStyle=pal[1];ctx.beginPath();ctx.arc(w*.5,h*.45,Math.min(w,h)*.23,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.12;for(let i=0;i<9;i++){let x=(i/8)*w;ctx.fillStyle=i%2?pal[2]:'#ddd';ctx.fillRect(x,h*.18,1,h*.45)}ctx.restore();const gy=h*.76;ctx.fillStyle='#111016';ctx.beginPath();ctx.moveTo(0,gy);ctx.lineTo(w,gy);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.strokeStyle=pal[1]+'55';ctx.lineWidth=1;for(let i=0;i<8;i++){const y=gy+(h-gy)*i/8;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}for(let i=0;i<11;i++){let x=i*w/10;ctx.beginPath();ctx.moveTo(w*.5,gy);ctx.lineTo(x,h);ctx.stroke()}ctx.strokeStyle=pal[2]+'99';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,gy);ctx.lineTo(w,gy);ctx.stroke();ctx.fillStyle='#ffffff07';ctx.fillRect(0,0,w,h);}
function renderFight(t,w,h){drawArena(w,h,t);if(!fight)return;const s=clamp(Math.min(w/900,h/560),.76,1.4),ground=h*.76,center=w*.5,span=Math.min(w*.38,320*s);const p=fight.player,e=fight.enemy;const px=center+clamp(p.x,-1,1)*span,ex=center+clamp(e.x,-1,1)*span;ctx.save();ctx.globalAlpha=.25;ctx.strokeStyle='#eee';ctx.setLineDash([6,8]);ctx.beginPath();ctx.moveTo(center,ground);ctx.lineTo(center,h);ctx.stroke();ctx.restore();drawChar(ctx,px,ground,s,fighters[playerIndex],t,p.facing,p.pose,profile.skin);drawChar(ctx,ex,ground,s,fighters[enemyIndex],t,e.facing,e.pose,0);if(p.pose==='attack'&&t<p.poseUntil){ctx.globalAlpha=.55;ctx.strokeStyle=fighters[playerIndex].accent;ctx.lineWidth=4;ctx.beginPath();ctx.arc(px+p.facing*50*s,ground-72*s,22*s,-1,1);ctx.stroke();ctx.globalAlpha=1}if(e.pose==='attack'&&t<e.poseUntil){ctx.globalAlpha=.5;ctx.strokeStyle=fighters[enemyIndex].accent;ctx.lineWidth=4;ctx.beginPath();ctx.arc(ex+e.facing*50*s,ground-72*s,20*s,-1,1);ctx.stroke();ctx.globalAlpha=1}}
function stepFight(dt,t){if(!fight||fight.paused||fight.over)return;const p=fight.player,e=fight.enemy;let axis=moveAxis;if(keys.ArrowLeft||keys.a||keys.A)axis-=1;if(keys.ArrowRight||keys.d||keys.D)axis+=1;axis=clamp(axis,-1,1);const speed=1.05+fighters[playerIndex].stats[1]/210;p.x=clamp(p.x+axis*speed*dt,-1,1);if(axis)p.facing=axis>0?1:-1;p.guard=keys.Shift||keys[' '];if(!p.guard&&p.pose==='block')p.pose='idle';if(p.poseUntil<t&&(p.pose==='attack'||p.pose==='hit'))p.pose='idle';if(e.poseUntil<t&&(e.pose==='attack'||e.pose==='hit'))e.pose='idle';const delta=e.x-p.x;e.facing=delta>=0?-1:1;aiClock-=dt;if(aiClock<=0){aiClock=rand(.3,.72);const distance=Math.abs(delta);if(distance>.24)e.x-=Math.sign(delta)*rand(.1,.2);else if(Math.random()<.58){e.pose='attack';e.poseUntil=t+.3;const dmg=rand(7,12)*(fighters[enemyIndex].stats[0]/75);if(p.guard)dmg*=.22;p.hp=Math.max(0,p.hp-dmg);e.ult=Math.min(100,e.ult+10);p.ult=Math.min(100,p.ult+dmg*.5);if(p.hp<=0)finishFight(false)}else if(Math.random()<.5)e.guard=true;else e.guard=false}if(Math.abs(delta)>.31)e.guard=false;if(p.guard)p.pose='block';else if(p.pose==='block')p.pose='idle';updateHud()}
