function actionForKey(key){const k=key.toLowerCase();return ({j:'attack',k:'skill1',l:'skill2',';':'skill3',u:'ult'})[k]}
function releaseBlock(){if(fight?.player){fight.player.guard=false;if(fight.player.pose==='block')fight.player.pose='idle'}}
