function setJoystick(event){const r=$('#joystick').getBoundingClientRect(),cx=r.left+r.width/2,dx=event.clientX-cx;moveAxis=clamp(dx/(r.width*.34),-1,1);$('#joyKnob').style.transform=`translate(${moveAxis*30}px,${clamp(event.clientY-(r.top+r.height/2),-25,25)}px)`}
const joystick=$('#joystick');joystick.addEventListener('pointerdown',event=>{event.preventDefault();joystick.setPointerCapture(event.pointerId);setJoystick(event)});joystick.addEventListener('pointermove',event=>{if(joystick.hasPointerCapture(event.pointerId))setJoystick(event)});const resetJoystick=()=>{moveAxis=0;$('#joyKnob').style.transform='translate(0,0)'};joystick.addEventListener('pointerup',resetJoystick);joystick.addEventListener('pointercancel',resetJoystick);joystick.addEventListener('lostpointercapture',resetJoystick);
